// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot) public {
        vm.assume(baseToken != address(0));
        vm.assume(feeRate <= 5_000);
        c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, false, false);
        assertTrue(c.baseToken() == baseToken);
